// Signed sponsored-message provider for isolated Layer 229 acceptance probes.
//
// The fixture is deliberately stateless. It validates the exact request id and
// idempotency key generated by the sponsored-messages BFF, then derives stable
// TL payloads from the authenticated user and request payload.
package main

import (
	"context"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/teamgram/teamgram-server/pkg/providercontract"
)

const (
	defaultPort    = "23195"
	bodyLimit      = 1 << 20
	requestHeader  = "X-Teamgram-Sponsored-Provider-Request-Signature"
	responseHeader = "X-Teamgram-Sponsored-Provider-Signature"
)

type requestEnvelope struct {
	RequestID string          `json:"request_id"`
	Operation string          `json:"operation"`
	UserID    int64           `json:"user_id"`
	Payload   json.RawMessage `json:"payload"`
}

type server struct {
	key     string
	authKey string
	query   string
	peerID  int64
	maxAge  time.Duration
}

func (s *server) sign(body []byte) string {
	return providercontract.Signature(s.key, body)
}

func (s *server) writeEnvelope(w http.ResponseWriter, request requestEnvelope, result any, providerErr error) {
	response := providercontract.ResponseEnvelope{
		RequestID: request.RequestID,
		Operation: request.Operation,
		Verified:  true,
		UserID:    request.UserID,
	}
	if providerErr != nil {
		response.Error = providerErr.Error()
	} else {
		encoded, err := json.Marshal(result)
		if err != nil {
			response.Verified = false
			response.Error = "result encoding failed"
		} else {
			response.Result = encoded
		}
	}
	body, err := json.Marshal(response)
	if err != nil {
		http.Error(w, "response encoding failed", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set(responseHeader, s.sign(body))
	_, _ = w.Write(body)
}

func (s *server) handle(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	if !validBearerAuthorization(r.Header.Get("Authorization"), s.authKey) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, bodyLimit+1))
	if err != nil || len(body) == 0 || len(body) > bodyLimit || !providercontract.VerifySignature(s.key, r.Header.Get(requestHeader), body) {
		http.Error(w, "invalid signed request", http.StatusUnauthorized)
		return
	}
	var request requestEnvelope
	if err = json.Unmarshal(body, &request); err != nil || request.RequestID == "" || request.Operation == "" || request.UserID <= 0 || len(request.Payload) == 0 || string(request.Payload) == "null" {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}
	ctx, cancel := contextWithRequestTimeout(r, s.maxAge)
	defer cancel()
	result, providerErr := s.dispatch(ctx, request, r.Header.Get("Idempotency-Key"))
	s.writeEnvelope(w, request, result, providerErr)
}

func validBearerAuthorization(value, expected string) bool {
	if expected == "" {
		return true
	}
	provided := strings.TrimPrefix(value, "Bearer ")
	if provided == value || provided == "" {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(provided), []byte(expected)) == 1
}

func contextWithRequestTimeout(r *http.Request, maxAge time.Duration) (context.Context, context.CancelFunc) {
	if maxAge <= 0 {
		return context.WithCancel(r.Context())
	}
	return context.WithTimeout(r.Context(), maxAge)
}

func (s *server) healthz(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.WriteHeader(http.StatusMethodNotAllowed)
		return
	}
	w.WriteHeader(http.StatusOK)
}

func sponsoredRequestID(operation string, userID int64, payload []byte) string {
	digest := sha256.Sum256(append([]byte(operation+":"+strconv.FormatInt(userID, 10)+":"), payload...))
	return fmt.Sprintf("%x", digest[:])
}

func (s *server) dispatch(ctx context.Context, request requestEnvelope, idempotencyKey string) (any, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	expectedID := sponsoredRequestID(request.Operation, request.UserID, request.Payload)
	if request.RequestID != expectedID || idempotencyKey != expectedID {
		return nil, errors.New("request_id and idempotency key do not match payload")
	}
	switch request.Operation {
	case "contacts.getSponsoredPeers":
		return s.sponsoredPeers(request)
	case "messages.getSponsoredMessages":
		return s.sponsoredMessages(request)
	default:
		return nil, fmt.Errorf("operation %q is not provisioned", request.Operation)
	}
}

func (s *server) sponsoredPeers(request requestEnvelope) (any, error) {
	var payload struct {
		Q string `json:"q"`
	}
	if err := json.Unmarshal(request.Payload, &payload); err != nil {
		return nil, errors.New("payload must be an object")
	}
	query := strings.TrimSpace(payload.Q)
	if query == "" || (s.query != "" && query != s.query) {
		return nil, errors.New("query is not provisioned")
	}
	randomID := stableRandomID(request.UserID, request.Operation, request.Payload)
	return map[string]any{
		"predicate_name": "contacts_sponsoredPeers",
		"constructor":    -352114556,
		"peers": []any{map[string]any{
			"predicate_name": "sponsoredPeer",
			"constructor":    -963180333,
			"random_id":      randomID,
			"peer": map[string]any{
				"predicate_name": "peerUser",
				"constructor":    1498486562,
				"user_id":        s.peerID,
			},
			"sponsor_info": map[string]any{"value": fmt.Sprintf("fixture-user-%d", request.UserID)},
		}},
		"chats": []any{},
		"users": []any{map[string]any{
			"predicate_name": "user",
			"id":             s.peerID,
			"username":       map[string]any{"value": "sponsored_fixture"},
		}},
	}, nil
}

func (s *server) sponsoredMessages(request requestEnvelope) (any, error) {
	var payload struct {
		Peer  json.RawMessage `json:"peer"`
		MsgID *int32          `json:"msg_id"`
	}
	if err := json.Unmarshal(request.Payload, &payload); err != nil || len(payload.Peer) == 0 || string(payload.Peer) == "null" {
		return nil, errors.New("peer is required")
	}
	var peer struct {
		PredicateName string `json:"predicate_name"`
		UserID        int64  `json:"user_id"`
		ChatID        int64  `json:"chat_id"`
		ChannelID     int64  `json:"channel_id"`
	}
	if err := json.Unmarshal(payload.Peer, &peer); err != nil || strings.TrimSpace(peer.PredicateName) == "" {
		return nil, errors.New("peer predicate is required")
	}
	switch peer.PredicateName {
	case "inputPeerSelf":
	case "inputPeerUser":
		if peer.UserID <= 0 {
			return nil, errors.New("inputPeerUser user_id must be positive")
		}
	case "inputPeerChat":
		if peer.ChatID <= 0 {
			return nil, errors.New("inputPeerChat chat_id must be positive")
		}
	case "inputPeerChannel":
		if peer.ChannelID <= 0 {
			return nil, errors.New("inputPeerChannel channel_id must be positive")
		}
	default:
		return nil, fmt.Errorf("peer predicate %q is not provisioned", peer.PredicateName)
	}
	if payload.MsgID != nil && *payload.MsgID <= 0 {
		return nil, errors.New("msg_id must be positive")
	}
	randomID := stableRandomID(request.UserID, request.Operation, request.Payload)
	return map[string]any{
		"predicate_name": "messages_sponsoredMessages",
		"constructor":    -2464403,
		"messages": []any{map[string]any{
			"predicate_name": "sponsoredMessage",
			"constructor":    2109703795,
			"recommended":    true,
			"can_report":     true,
			"random_id":      randomID,
			"url":            "https://sponsored-provider-fixture.invalid/ad",
			"title":          "Teamgram provider fixture",
			"message":        fmt.Sprintf("signed sponsored fixture for user %d", request.UserID),
			"sponsor_info":   map[string]any{"value": fmt.Sprintf("fixture-user-%d", request.UserID)},
		}},
		"chats": []any{},
		"users": []any{},
	}, nil
}

func stableRandomID(userID int64, operation string, payload []byte) string {
	digest := sha256.Sum256([]byte(strconv.FormatInt(userID, 10) + ":" + operation + ":" + string(payload)))
	return base64.StdEncoding.EncodeToString(digest[:16])
}

func configure() (*server, string, error) {
	key := strings.TrimSpace(os.Getenv("SPONSORED_PROVIDER_SIGNING_KEY"))
	if len(key) < 32 {
		return nil, "", errors.New("SPONSORED_PROVIDER_SIGNING_KEY must contain at least 32 bytes")
	}
	authKey := strings.TrimSpace(os.Getenv("SPONSORED_PROVIDER_KEY"))
	if authKey == "" {
		return nil, "", errors.New("SPONSORED_PROVIDER_KEY must be set")
	}
	port := strings.TrimSpace(os.Getenv("SPONSORED_PROVIDER_PORT"))
	if port == "" {
		port = defaultPort
	}
	portNumber, err := strconv.Atoi(port)
	if err != nil || portNumber < 1 || portNumber > 65535 {
		return nil, "", errors.New("SPONSORED_PROVIDER_PORT must be an integer from 1 to 65535")
	}
	peerID := int64(900000000001)
	if value := strings.TrimSpace(os.Getenv("SPONSORED_PROVIDER_PEER_USER_ID")); value != "" {
		peerID, err = strconv.ParseInt(value, 10, 64)
		if err != nil || peerID <= 0 {
			return nil, "", errors.New("SPONSORED_PROVIDER_PEER_USER_ID must be positive")
		}
	}
	maxAge := 5 * time.Second
	if value := strings.TrimSpace(os.Getenv("SPONSORED_PROVIDER_TIMEOUT_SECONDS")); value != "" {
		seconds, parseErr := strconv.Atoi(value)
		if parseErr != nil || seconds < 0 || seconds > 300 {
			return nil, "", errors.New("SPONSORED_PROVIDER_TIMEOUT_SECONDS must be from 0 to 300")
		}
		if seconds > 0 {
			maxAge = time.Duration(seconds) * time.Second
		}
	}
	return &server{
		key:     key,
		authKey: authKey,
		query:   strings.TrimSpace(os.Getenv("SPONSORED_PROVIDER_QUERY")),
		peerID:  peerID,
		maxAge:  maxAge,
	}, port, nil
}

func main() {
	s, port, err := configure()
	if err != nil {
		log.Fatal(err)
	}
	if len(os.Args) == 2 && os.Args[1] == "--healthcheck" {
		return
	}
	if len(os.Args) > 1 {
		log.Fatal("unsupported argument")
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", s.healthz)
	mux.HandleFunc("/", s.handle)
	log.Printf("sponsored provider fixture listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, mux))
}
